import { markerGroupKey } from './marker-group-key.js';
import { overrideMarkerProps } from './override-marker-props.js';
import { WithId } from '../../../types/with-id.js';
import { DEFAULT_PRIORITY } from '../constants.js';
import { AnnotationGroup, AnnotationData } from '../types/annotations.js';
import { MarkerProps } from '../types/markers.js';
import { TrackProps } from '../types/tracks.js';

/**
 * Process annotation markers.
 * That includes sorting and grouping by time, and overriding markers with track props.
 *
 * @param markers - markers to process
 * @param trackProps - track props to override markers with
 * @returns processed markers
 */
export function processAnnotationTracksData(
  trackProps: TrackProps,
): Map<string, AnnotationGroup[]> {
  const { markers } = trackProps;

  const processedMarkers = new Map<string, AnnotationGroup[]>();
  const sortedMarkers = sortAnnotationsByTime(markers);
  let lastProcessedGroupKey = '';

  for (let i = 0; i < sortedMarkers.length; i++) {
    const marker = sortedMarkers[i];

    if (marker.hidden) {
      continue;
    }

    const annotation: AnnotationData = overrideMarker(marker, trackProps);

    const annotationKey = markerGroupKey(annotation.start, annotation.end);
    const annotationStart = annotation.start.getTime();
    const annotationEnd = annotation.end
      ? annotation.end.getTime()
      : annotationStart;

    if (!lastProcessedGroupKey) {
      processedMarkers.set(annotationKey, [
        createGroup(annotation, annotationKey),
      ]);
      lastProcessedGroupKey = annotationKey;
      continue;
    }

    const [lastGroupStart, lastGroupEnd] = lastProcessedGroupKey
      .split('_')
      .map(Number);
    const isOverlapping = overlapsWithTheLastGroup(
      lastGroupStart,
      lastGroupEnd,
      annotationStart,
      annotationEnd,
    );

    if (!isOverlapping) {
      processedMarkers.set(annotationKey, [
        createGroup(annotation, annotationKey),
      ]);

      lastProcessedGroupKey = annotationKey;
      continue;
    }

    // Logic for overlapping annotations
    const groups: AnnotationGroup[] = processedMarkers.get(
      lastProcessedGroupKey,
    )!;
    const sameKeyGroup = groups.find((group) => group.key === annotationKey);

    // logic for repeated annotations
    if (sameKeyGroup) {
      sameKeyGroup.annotations.push(annotation);
      const priority = annotation.priority ?? DEFAULT_PRIORITY;
      sameKeyGroup.priority = Math.max(sameKeyGroup.priority, priority);

      continue;
    }

    const updatedGroupsKey: string = [
      Math.min(lastGroupStart, annotationStart),
      Math.max(lastGroupEnd, annotationEnd),
    ].join('_');

    if (updatedGroupsKey === lastProcessedGroupKey) {
      const newInnerGroup: AnnotationGroup = createGroup(
        annotation,
        annotationKey,
      );
      groups.push(newInnerGroup);

      continue;
    }

    groups.push(createGroup(annotation, annotationKey));
    processedMarkers.set(updatedGroupsKey, groups);
    processedMarkers.delete(lastProcessedGroupKey);

    lastProcessedGroupKey = updatedGroupsKey;
  }

  return processedMarkers;
}

/**
 * Sorts annotations by start time and end time.
 *
 * @param annotations - annotations to sort
 * @returns sorted annotations
 */
const sortAnnotationsByTime = (
  annotations: WithId<MarkerProps>[],
): WithId<MarkerProps>[] =>
  annotations.sort((a, b) => {
    const aStart = a.data.start.getTime();
    const bStart = b.data.start.getTime();
    const aEnd = a.data.end ? a.data.end.getTime() : aStart;
    const bEnd = b.data.end ? b.data.end.getTime() : bStart;

    if (aStart === bStart) {
      return aEnd - bEnd;
    }

    return a.data.start.getTime() - b.data.start.getTime();
  });

/**
 * Override missing marker props (e.g. color, symbol) with track props.
 * Marker props have higher priority than track's.
 *
 * @param marker - marker to override
 * @param trackProps - track props
 * @returns overridden marker
 */
const overrideMarker = (
  marker: WithId<MarkerProps>,
  trackProps: TrackProps,
): AnnotationData => {
  const { data, ...markerProps } = marker;

  return {
    ...marker.data,
    ...markerProps,
    ...overrideMarkerProps(markerProps, trackProps),
  };
};

/**
 * Creates a new group with a single annotation in it
 *
 * @param annotation - a single annotation to creat a group with
 * @param key - key of the group ("start_end" of the annotation)
 * @returns a new group with a single annotation in it
 */
const createGroup = (
  annotation: AnnotationData,
  key: string,
): AnnotationGroup => ({
  annotations: [annotation],
  priority: annotation.priority ?? DEFAULT_PRIORITY,
  key: key,
  start: annotation.start,
  end: annotation.end ? annotation.end : annotation.start,
});

/**
 * Checks if the annotation overlaps with the last group
 *
 * @param groupStart - start of the last group
 * @param groupEnd - end of the last group
 * @param start - start of the annotation
 * @param end - end of the annotation
 */
const overlapsWithTheLastGroup = (
  groupStart: number,
  groupEnd: number,
  start: number,
  end: number,
): boolean =>
  (start >= groupStart && start <= groupEnd) ||
  (end >= groupStart && end <= groupEnd);
